import{_ as t,c as a,o as r,a3 as s}from"./chunks/framework.Dokpd4od.js";const p=JSON.parse('{"title":"Selling at the terminal","description":"","frontmatter":{},"headers":[],"relativePath":"master/sales/point-of-sale/selling/index.md","filePath":"master/sales/point-of-sale/selling/index.md","lastUpdated":1792041590000}'),o={name:"master/sales/point-of-sale/selling/index.md"};function n(i,e,l,d,h,c){return r(),a("div",null,e[0]||(e[0]=[s('<h1 id="selling-at-the-terminal" tabindex="-1">Selling at the terminal <a class="header-anchor" href="#selling-at-the-terminal" aria-label="Permalink to &quot;Selling at the terminal&quot;">​</a></h1><p>The terminal is the till screen your cashiers use all day. It runs in the browser, so any computer, tablet or touch screen can be a register. This group shows the whole selling flow, from the first product on an order to the receipt, a refund or an invoice.</p><blockquote><p><strong>In simple words:</strong> Open the register, add products, take payment, hand over the receipt. Everything else is an option on top.</p></blockquote><h2 id="the-selling-flow" tabindex="-1">The selling flow <a class="header-anchor" href="#the-selling-flow" aria-label="Permalink to &quot;The selling flow&quot;">​</a></h2><ol><li><strong>Open the register.</strong> Confirm the opening cash. See <a href="./../sessions/open-register.html">Open the register</a>.</li><li><strong>Start an order.</strong> In a shop, pick products. In a restaurant, click a table first. See <a href="./take-an-order.html">Take an order</a> and <a href="./restaurant-tables.html">Restaurant tables</a>.</li><li><strong>Add details.</strong> Pick a customer, add notes, change quantity or price. See <a href="./order-notes-and-customers.html">Notes and customers</a>.</li><li><strong>Take payment.</strong> Choose a method, enter the amount and click <strong>Validate</strong>. See <a href="./pay-and-receipt.html">Pay and receipt</a>.</li><li><strong>After the sale.</strong> Refund a product, or create an invoice for a customer. See <a href="./refunds.html">Refunds</a> and <a href="./invoice-a-pos-order.html">Invoice a POS order</a>.</li><li><strong>Close the register.</strong> Count the cash at the end of the day. See <a href="./../sessions/close-session.html">Close a session</a>.</li></ol><h2 id="order-statuses" tabindex="-1">Order statuses <a class="header-anchor" href="#order-statuses" aria-label="Permalink to &quot;Order statuses&quot;">​</a></h2><p>An order moves through these statuses.</p><ul><li><strong>New:</strong> The order is open and not paid.</li><li><strong>Paid:</strong> The customer paid. The order waits for the session to close.</li><li><strong>Posted:</strong> The session closed and the sale went to accounting.</li><li><strong>Invoiced:</strong> A customer invoice was created for the order.</li><li><strong>Cancelled:</strong> The order was cancelled before payment.</li></ul><h2 id="pages-in-this-group" tabindex="-1">Pages in this group <a class="header-anchor" href="#pages-in-this-group" aria-label="Permalink to &quot;Pages in this group&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Page</th><th>Use it to</th></tr></thead><tbody><tr><td><a href="./terminal-overview.html">Terminal tour</a></td><td>Learn every area of the screen</td></tr><tr><td><a href="./take-an-order.html">Take an order</a></td><td>Sell products in a shop</td></tr><tr><td><a href="./order-notes-and-customers.html">Notes and customers</a></td><td>Add notes and pick a customer</td></tr><tr><td><a href="./restaurant-tables.html">Restaurant tables</a></td><td>Use the floor plan and table orders</td></tr><tr><td><a href="./pay-and-receipt.html">Pay and receipt</a></td><td>Take payment and print the receipt</td></tr><tr><td><a href="./refunds.html">Refunds</a></td><td>Return products and pay the money back</td></tr><tr><td><a href="./invoice-a-pos-order.html">Invoice a POS order</a></td><td>Create a customer invoice from a sale</td></tr></tbody></table><h2 id="two-examples-used-in-this-guide" tabindex="-1">Two examples used in this guide <a class="header-anchor" href="#two-examples-used-in-this-guide" aria-label="Permalink to &quot;Two examples used in this guide&quot;">​</a></h2><p><strong>TechNest Electronics</strong> is a retail shop. The cashier sells two Glide Wireless Mouse and one BudsAir Wireless Earbuds to Sofia Rossi for 6,597. She pays 7,000 in cash and gets 403 back.</p><p><strong>Spice Route Kitchen &amp; Bar</strong> is a restaurant. The waiter opens table T4 and adds Butter Chicken x2, Margherita Pizza and Mango Lassi x2. The total is 1,405.</p><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./../sessions/">Register sessions</a></li><li><a href="./../get-started/set-up-a-register.html">Set up a register</a></li><li><a href="./../payments-setup/payment-methods.html">Payment methods</a></li></ul>',15)]))}const g=t(o,[["render",n]]);export{p as __pageData,g as default};
